class Solution {
public:
    int findKthPositive(vector<int>& arr, int k) {
        // Your code goes here
        int low = 0;
        int high = arr.size() - 1;

        while(low <= high){
            int mid = low + (high - low) / 2;
            int lost = arr[mid] - 1 - mid;

            if(lost < k){
                low = mid + 1;
            }else{
                // ans = mid;
                high = mid - 1;
            }
        }
        return low + k;
    }
};

```

